const status = String(msg.payload.status || 'NORMAL');
const motorState = String(msg.payload.motor_state || 'ON');
const vibration = Number(msg.payload.vibration || 0);
const confidence = Number(msg.payload.ai_confidence || 0) * 100;
const timestamp = new Date((msg.payload.timestamp || Date.now() / 1000) * 1000);
const timeLabel = timestamp.toLocaleTimeString([], { hour12: false });
const normalizedStatus = motorState === 'OFF' || status === 'MOTOR_OFF' ? 'MOTOR OFF' : status;
const lastState = context.get('lastState');
const shouldLog = normalizedStatus === 'FAULT' || normalizedStatus !== lastState;

if (!shouldLog) {
    return null;
}

const entryType = normalizedStatus === 'FAULT'
    ? 'history-entry--fault'
    : normalizedStatus === 'MOTOR OFF'
        ? 'history-entry--stopped'
        : '';
const detail = normalizedStatus === 'FAULT'
    ? 'Abnormal vibration at ' + vibration.toFixed(4) + ' g with AI confidence ' + confidence.toFixed(1) + '%.'
    : normalizedStatus === 'MOTOR OFF'
        ? 'Motor relay is OFF. Last reading was ' + vibration.toFixed(4) + ' g.'
        : 'System returned to normal at ' + vibration.toFixed(4) + ' g.';

const history = context.get('history') || [];
history.unshift('<div class="history-entry ' + entryType + '"><div class="history-entry__top"><span class="history-entry__status">' + normalizedStatus + '</span><span class="history-entry__time">' + timeLabel + '</span></div><div class="history-entry__detail">' + detail + '</div></div>');
context.set('history', history.slice(0, 8));
context.set('lastState', normalizedStatus);
msg.payload = '<div class="history-list">' + context.get('history').join('') + '</div>';
return msg;
